    {"id": "v03-tablier", "cat": "berth", "tier": "berth_top", "priority": 2, "badge": "GAULT&MILLAU 2026", "name": "Ô Tablier", "short": "Ô Tablier", "lat": 46.6743, "lng": 5.5527, "tags": [], "productTags": ["Contemporary", "Traditional"], "why": "The dining room sits a few steps below the street, small enough that the kitchen is never far. The menu is short, three or four starters and mains, and diners say it changes monthly. Gault&Millau's 2026 reviewer ate a crust of morels in Vin Jaune, fondues, duck with Macvin and a dessert pairing goat's cheese with chocolate, and found a cellar of Jura bottles to match.", "address": "20 rue Émile Monot, 39000 Lons-le-Saunier", "phone": "+33 3 84 24 26 59", "hours": "Year-round as far as found; no annual or Christmas closure published. Open now (late Oct): yes on its days. November-December: no closure found, call ahead · Call ahead: PagesJaunes (updated 22 April 2026) shows Mon, Thu, Fri lunch and 19:00-21:00 dinner, Tue and Sat lunch only, closed Wed and Sun; Cylex and trouver-ouvert (Feb 2026) show Fri and Sat starting at 12:00", "maps": "https://www.google.com/maps/search/?api=1&query=Ô+Tablier+Lons-le-Saunier", "price_range": "About 36-42 euros a head without drinks (seen Oct 2026, Gault&Millau)", "status": "confirmed", "statusChecked": "2026-10-26", "hook": "A 32-cover bistro on rue Émile Monot with a short regional menu built for sharing.", "verdict": "The most local cooking inside Lons, at prices that suit a crew lunch, but it is a modest bistro, not a destination: Gault&Millau selects it without a score. The room is tiny and the opening hours are irregular and disputed, so phone the same morning. Order the morel crust and whatever Jura white the cellar suggests.", "signature": "Croûte aux morilles au Vin Jaune", "caveat": "Tiny room; closed Wednesday and Sunday, dinner only some days; hours differ between listings, call first", "dishes": [{"name": "Croûte aux morilles au Vin Jaune", "note": "Morels in Vin Jaune cream on toast, in Gault&Millau's 2026 review", "kind": "dish"}, {"name": "Fondue", "note": "Named in Gault&Millau 2026; the Comté course in sharing form", "kind": "dish"}, {"name": "Roast duck fillet with Macvin", "note": "Gault&Millau 2026", "kind": "dish"}, {"name": "Apple brick with smoked raclette", "note": "A sweet-salty plate listed by Gault&Millau", "kind": "dish"}, {"name": "Goat's cheese and chocolate dessert", "note": "Gault&Millau 2026", "kind": "sweet"}, {"name": "Comté and Macvin ice cream", "note": "On Gault&Millau's earlier list of plates", "kind": "sweet"}], "reservation": "Book by phone; 32 covers (Jura Tourisme)", "neighborhood": "Rue Émile Monot", "signal_chip": {"label": "G&M 2026", "full": "Gault&Millau 2026: selected (no score), one of five Lons restaurants in the guide", "cosign": "Jura Tourisme listing; PagesJaunes (April 2026)"}, "category": "lons", "charter": {"price": "About 36-42 euros a head without drinks (seen Oct 2026, Gault&Millau)", "book": "Book by phone; 32 covers (Jura Tourisme)", "warn": "Tiny room; closed Wednesday and Sunday, dinner only some days; hours differ between listings, call first", "fit": "A 32-cover bistro on rue Émile Monot with a short regional menu built for sharing."}},
    {"id": "v05-la-petite-auberge", "cat": "shop", "tier": "several", "priority": 5, "badge": "GAULT&MILLAU 11/20", "name": "La Petite Auberge", "short": "La Petite Auberge", "lat": 46.694, "lng": 5.5648, "tags": [], "productTags": ["Contemporary"], "why": "Out on the route de Besançon at the northern edge of Lons, with free parking at the door, this is where the region's classic plates are cooked straight: a crust of morels in Vin Jaune, Jura trout with roasted bacon, and for dessert a soufflé glacé flavoured with Macvin, the Jura's grape-must-and-marc aperitif, or griottine cherries from Fougerolles. Gault&Millau calls it quiet and steady.", "address": "1985 route de Besançon, 39000 Lons-le-Saunier", "phone": "+33 3 84 47 23 35", "hours": "Year-round as far as found; no annual or Christmas closure published. Open now (late Oct): yes on its days. November-December: no closure found, call ahead · Call ahead: most listings show lunch Mon-Fri and Sun (12:00-14:00), dinner Tue-Fri, closed Saturday; the Lons tourist office lists a Saturday dinner", "maps": "https://www.google.com/maps/search/?api=1&query=La+Petite+Auberge+Lons-le-Saunier", "price_range": "About 22-47 euros a head without drinks; Menu des Gourmets 47 euros (seen Oct 2026, Gault&Millau; the English page shows 32-45)", "status": "confirmed", "statusChecked": "2026-10-26", "hook": "A roadside auberge on the Besançon road keeping the Jura classics, ending on a Macvin soufflé glacé.", "verdict": "A safe traditional dinner close to town, rated 11/20 by Gault&Millau, with the 47 euro Menu des Gourmets as the full tour. Diner reviews are mixed: an August 2026 TripAdvisor review complained of a cool welcome and prices, while others praise the cooking. Go for the classics and the soufflé, not for a polished service.", "signature": "Soufflé glacé au Macvin", "caveat": "Hours disputed between listings (Saturday especially); a car or taxi from the centre; reviews mention cool service", "dishes": [{"name": "Croûte aux morilles et Vin Jaune", "note": "Named by Gault&Millau", "kind": "dish"}, {"name": "Jura trout with roasted bacon", "note": "Named by Gault&Millau", "kind": "dish"}, {"name": "Menu des Gourmets", "note": "47 euros, the long menu (Gault&Millau, French page)", "kind": "dish"}, {"name": "Soufflé glacé au Macvin", "note": "The regional iced soufflé, named by Gault&Millau", "kind": "sweet"}, {"name": "Griottines de Fougerolles", "note": "Kirsch-soaked cherries from the Haute-Saône, on the dessert list", "kind": "sweet"}], "reservation": "Phone to book and confirm the day", "neighborhood": "Route de Besançon", "signal_chip": {"label": "G&M 11/20", "full": "Gault&Millau: 11/20 (2025 review), still in the guide's Lons selection", "cosign": "Lons-le-Saunier tourist office; TripAdvisor review dated August 2026"}, "category": "lons"},
    {"id": "v06-le-bistrot-des-marronniers", "cat": "shop", "tier": "several", "priority": 6, "badge": "GAULT&MILLAU 2026", "name": "Le Bistrot des Marronniers", "short": "Le Bistrot des Marronnie", "lat": 46.6757, "lng": 5.5543, "tags": [], "productTags": ["Traditional", "Wine"], "why": "The menu runs on two tracks: Lyonnais bouchon plates such as tablier de sapeur, breaded and fried tripe, beside Jura recipes such as an oeuf cocotte with Comté and Macvin sauce. The meat is grilled on a wood-burning stove set in the centre of the dining room, so the room smells of the fire. Gault&Millau 2026 calls it Lons's institutional brasserie, where people come for business lunches.", "address": "22 rue de Vallière, 39000 Lons-le-Saunier", "phone": "+33 3 84 43 06 04", "hours": "Year-round as far as found; no annual or Christmas closure published. Open now (late Oct): yes on its days. November-December: no closure found, call ahead · Call ahead: own site shows Mon lunch, Tue-Fri 12:00-14:30 and 19:00-22:30, Sat dinner, closed Sun; Yelp (July 2026) and PagesJaunes show lunch and dinner Mon-Fri (dinner 19:30-21:30), Sat dinner, closed Sun", "maps": "https://www.google.com/maps/search/?api=1&query=Le+Bistrot+des+Marronniers+Lons-le-Saunier", "price_range": "Market menu 37.95 euros (seen Oct 2026, Gault&Millau)", "reservation": "Phone; walk-in possible outside business-lunch hours", "status": "confirmed", "statusChecked": "2026-10-26", "hook": "Half Lyon bouchon, half Jura kitchen, with meat grilled on a wood stove in the middle of the room.", "verdict": "A reliable, generous table rather than a fine one: Gault&Millau's 2026 entry keeps it in the guide with a market menu at 37.95 euros, and recent reviews praise the welcome. Order from the fire or the pike quenelle. Hours vary between listings, but it serves both lunch and dinner on most weekdays, which makes it the easiest booking in town.", "signature": "Meat from the wood-fired grill, or the pike quenelle", "caveat": "Closed Sunday; Monday and Saturday hours disputed between listings; busy with business lunches", "dishes": [{"name": "Tablier de sapeur", "note": "Lyonnais breaded tripe, the bouchon half of the menu", "kind": "dish"}, {"name": "Oeuf cocotte, Comté and Macvin sauce", "note": "In Gault&Millau's 2026 entry", "kind": "dish"}, {"name": "Croûte aux champignons", "note": "Mushroom crust, Gault&Millau 2026", "kind": "dish"}, {"name": "Quenelle de brochet", "note": "Pike quenelle, Gault&Millau 2026", "kind": "dish"}, {"name": "Grilled meat from the wood stove", "note": "Cooked on the stove in the centre of the room", "kind": "dish"}, {"name": "Market menu", "note": "37.95 euros (Gault&Millau 2026)", "kind": "dish"}], "web": "https://www.restaurant-le-bistrot-des-marronniers-lons-le-saunier.fr/", "neighborhood": "Rue de Vallière", "signal_chip": {"label": "G&M 2026", "full": "Gault&Millau 2026: in the guide as a traditional regional brasserie, market menu 37.95 euros", "cosign": "Petit Futé diner reviews (2025); Yelp listing (July 2026)"}, "category": "lons", "charter": {"price": "Market menu 37.95 euros (seen Oct 2026, Gault&Millau)", "book": "Phone; walk-in possible outside business-lunch hours", "warn": "Closed Sunday; Monday and Saturday hours disputed between listings; busy with business lunches", "fit": "Half Lyon bouchon, half Jura kitchen, with meat grilled on a wood stove in the middle of the room."}},
    {"id": "v08-la-finette-taverne-d-arbois", "cat": "shop", "tier": "several", "priority": 8, "badge": "JURA TAVERN", "name": "La Finette, Taverne d'Arbois", "short": "La Finette — Taverne d'A", "lat": 46.9027, "lng": 5.7786, "tags": [], "productTags": ["Traditional", "Wine"], "why": "La Finette has fed Arbois since 1961 from a timber-built room off avenue Pasteur: varnished log tables set round barrels, folk décor on every wall and a vaulted cellar below. The food is the Jura farmhouse canon served in quantity, from a pot of Comté fondue kept bubbling at the table to chicken deglazed with Vin Jaune and morels, Morteau sausage and Jura trout. The wine list stays inside the department, so it doubles as a first lesson in Savagnin and Trousseau.", "address": "22 avenue Pasteur, 39600 Arbois", "phone": "+33 3 84 66 06 78", "hours": "Year-round; no annual or Christmas closure found. Open now (late Oct, Toussaint holidays): yes, listed open every day. November-December: no closure published; check Christmas Eve and Day by phone · Call ahead: Jura Tourisme (listing valid from Feb 2026) shows open daily from 11:00; 118000.fr shows 11:30-14:30 and 18:30-22:30; the May 2026 record had daily 11:45-14:30 and 18:45-22:30", "maps": "https://www.google.com/maps/search/?api=1&query=La+Finette+—+Taverne+d%27Arbois+Lons-le-Saunier", "price_range": "About 30-57 € a head without drinks (Gault&Millau 2026, seen Oct 2026)", "status": "confirmed", "statusChecked": "2026-10-26", "hook": "Arbois's log-table tavern since 1961: Comté fondue, poulet au Vin Jaune, an all-Jura wine list.", "verdict": "Go for the room and the classics, not for finesse. Gault&Millau 2026 gives it 11/20 and says the technique does not always convince, probably because of the crowds, while praising the terrace, the mood and generous plates. Diners rate it highly on Google (4.6 from about 2,700 reviews). Order the fondue or the Vin Jaune chicken and drink a local bottle.", "signature": "Poulet (volaille) au Vin Jaune et morilles", "caveat": "In Arbois, about 40 km north of Lons by road; busy at weekends and in season, so book; hours vary by source, call ahead", "dishes": [{"name": "Fondue au Comté", "note": "The house classic, served at the log tables; listed at 20.50 € a head in May 2026, not re-checked", "kind": "dish"}, {"name": "Volaille au Vin Jaune et morilles", "note": "Named in Gault&Millau's 2026 review: the Jura cathedral dish", "kind": "dish"}, {"name": "Saucisse de Morteau", "note": "Smoked Haut-Doubs sausage, from the house record", "kind": "dish"}, {"name": "Jura trout", "note": "River fish on the regional menu, from the house record", "kind": "dish"}, {"name": "Franche-Comté ice cream with Fougerolles cherries", "note": "Kirsch-country cherries, from the house record", "kind": "sweet"}, {"name": "A bottle from the all-Jura list", "note": "Only Jura wines are poured: Savagnin, Trousseau, Ploussard", "kind": "drink"}], "reservation": "Recommended, by phone", "neighborhood": "Arbois", "signal_chip": {"label": "G&M 11/20", "full": "Gault&Millau 2026: 11/20, 'Table Gourmande'; in the Jura tavern trade since 1961", "cosign": "Jura Tourisme listing 2026; Google 4.6/5 (about 2,700 reviews)"}, "category": "wine", "hot_this_month": "Open every day by its record: fondue de Comté and poulet au Vin Jaune et morilles for a cold November evening.", "charter": {"price": "About 30-57 € a head without drinks (Gault&Millau 2026, seen Oct 2026)", "book": "Recommended, by phone", "warn": "In Arbois, about 40 km north of Lons by road; busy at weekends and in season, so book; hours vary by source, call ahead", "fit": "Arbois's log-table tavern since 1961: Comté fondue, poulet au Vin Jaune, an all-Jura wine list."}},
    {"id": "v09-le-bistrot-des-claquets", "cat": "shop", "tier": "several", "priority": 9, "badge": "NATURAL WINE BAR", "name": "Le Bistrot des Claquets", "short": "Le Bistrot des Claquets", "lat": 46.9012, "lng": 5.7754, "tags": [], "productTags": ["Wine", "Bacaro"], "why": "On Place Faramand in Arbois, the Claquets is a bar first: open from breakfast to about 9 in the evening, with a shelf of local natural wines instead of a printed list. At noon the kitchen sends out a single dish of the day with a buffet of cold starters, a formula Le Fooding priced at 12 € a plate and 16 to 19.50 € for the set. Growers come in for lunch, and some evenings there is music.", "address": "33 place Faramand, 39600 Arbois", "phone": "+33 3 84 66 04 19", "hours": "Year-round with short breaks. Open now (26 Oct): probably not, tourism listings post a closure 23 Oct-1 Nov (year not stated); with Sun-Mon closing, the likely reopening is Tue 3 Nov. November-December: no further closure found; Christmas dates not published · Tue-Sat about 08:00-21:00, lunch service at noon, bar the rest of the day; closed Sun-Mon (Pudlowski Aug 2023, Food Tourist; not confirmed for 2026)", "maps": "https://www.google.com/maps/search/?api=1&query=Le+Bistrot+des+Claquets+Lons-le-Saunier", "price_range": "Plates about 12 €, formulas 16-19.50 € (Le Fooding, undated; seen Oct 2026)", "status": "confirmed", "statusChecked": "2026-10-26", "hook": "Arbois's natural-wine cave à manger: one lunch dish a day, a cold buffet, a shelf of local bottles.", "verdict": "The cheapest serious lunch on the Arbois side and the easiest place to drink Arbois natural wine without an appointment. There is no choice at lunch, which is the point. June 2026 visitors on Raisin praise the room and the value. Book by phone for lunch; the tables go fast.", "signature": "The plat du jour with the cold-starter buffet, and a glass from the shelf", "caveat": "Lunch booking by phone only; closed Sunday and Monday; posted autumn break 23 Oct-1 Nov (year not stated); about 40 km from Lons", "dishes": [{"name": "Plat du jour", "note": "One main course a day, changed daily", "kind": "dish"}, {"name": "Cold-starter buffet", "note": "Comes with the lunch formula", "kind": "dish"}, {"name": "Entrée-plat-dessert formula", "note": "Listed at about 18 €; Le Fooding gives 16-19.50 € (undated)", "kind": "dish"}, {"name": "Aperitif board of regional charcuterie and cheese", "note": "For the bar hours, from the house record", "kind": "dish"}, {"name": "Jura natural wine by the glass or bottle", "note": "No list, a shelf of local growers' bottles", "kind": "drink"}], "reservation": "Lunch by phone only; walk-ins possible if there is room", "neighborhood": "Arbois", "signal_chip": {"label": "Le Fooding", "full": "Listed by Le Fooding as Arbois's natural-wine cave à manger; June 2026 reviews on Raisin", "cosign": "Gilles Pudlowski (2023); Jura Tourisme"}, "category": "wine"},
    {"id": "v12-march-de-lons-le-saunier", "cat": "berth", "tier": "berth_top", "priority": 3, "badge": "WEEKLY MARKET", "name": "Marché de Lons-le-Saunier", "short": "Marché de Lons-le-Saunie", "tags": [], "productTags": ["Market", "Produce", "Cheese"], "why": "On Thursday Lons fills two squares: a morning food market on Place de Verdun and a day of clothes and hardware on Place du 11 Novembre, from about 7 until 5. Saturday morning is smaller and food only, organic and short-chain stalls on Cours Sully. Late October is when Mont d'Or comes back in its spruce box, beside Comté of several ages, Morteau sausages with their wooden plug, jars of cancoillotte and fir honey.", "address": "Place de Verdun and Place du 11 Novembre (Thursday); Cours Sully (Saturday), 39000 Lons-le-Saunier", "phone": "", "hours": "Year-round weekly. Open now: Thursday 29 Oct (Toussaint holidays) is listed 7:00-17:00. November-December: weekly as usual; Christmas market dates for 2026 unconfirmed (one aggregator says 27 Nov 2026-3 Jan 2027, not officially confirmed; 2025 had a 13-14 Dec market on Place de la Liberté) · Thursday about 07:00-17:00: food market mornings on Place de Verdun, manufactured goods all day on Place du 11 Novembre; Saturday morning food-only (organic, short-chain) on Cours Sully (Jura Tourisme agenda and summer 2026 brochure)", "maps": "https://www.google.com/maps/search/?api=1&query=Marché+de+Lons-le-Saunier+Lons-le-Saunier", "price_range": "Stall prices vary", "reservation": "Walk-in", "status": "confirmed", "statusChecked": "2026-10-26", "hook": "The Jura's biggest weekly market: Thursday food on Place de Verdun, a Saturday organic market on Cours Sully.", "verdict": "Thursday morning is the one to plan around: the food stalls are on Place de Verdun and thin out by midday. Saturday is the quieter, greener version. The new mayor, elected in March 2026, has tested moving the Thursday market to Place de la Liberté and rue du Commerce, so check the squares before you go.", "signature": "Comté at two or three ages from one stall, and a Mont d'Or for the boat oven", "caveat": "Thursday food is mornings only; a permanent move to Place de la Liberté is under study, check the location", "dishes": [{"name": "Comté at several ages", "note": "Buy two ages from the same stall to taste the difference", "kind": "dish"}, {"name": "Mont d'Or AOP", "note": "In its spruce box, sold from late September to spring: in season now", "kind": "dish"}, {"name": "Saucisse de Morteau IGP", "note": "Smoked, sealed with a wooden peg; poach, never prick", "kind": "dish"}, {"name": "Cancoillotte", "note": "The runny low-fat Franche-Comté cheese, sold in jars", "kind": "dish"}, {"name": "Bleu de Gex", "note": "The mild Haut-Jura blue, at the cheese stalls", "kind": "dish"}, {"name": "Miel de sapin", "note": "Dark fir honey from the plateau", "kind": "sweet"}], "neighborhood": "Place de Verdun", "signal_chip": {"label": "Thu + Sat", "full": "Thursday is the largest market in the Jura department; Saturday morning organic food market", "cosign": "Jura Tourisme agenda 2026; info.fr (June 2026)"}, "category": "street", "hot_this_month": "Mont d'Or back on the cheese stalls, on sale since 10 September; four Thursday markets in November, 5 to 26."},
    {"id": "v-artisan-fromager", "cat": "shop", "tier": "plenty", "priority": 1, "name": "Chez l'Artisan Fromager", "short": "Chez l'Artisan Fromager", "lat": null, "lng": null, "tags": [], "productTags": ["Cheese"], "address": "39 rue du Commerce, 39000 Lons-le-Saunier", "maps": "https://www.google.com/maps/search/?api=1&query=Chez+l%27Artisan+Fromager+39+rue+du+Commerce+Lons-le-Saunier", "why": "The Poulet family have made cheese for four generations, and this shop at no. 39 rue du Commerce sells what they make: raclette cheese, tomme du Jura and above all Morbier. It sits under the stone arcades in the middle of Lons, so you can step out of the November rain into the smell of rind and cellar. Jura Tourisme lists it as both shop and producer, and the counter speaks French, German, Spanish and Italian.", "verdict": "The best-evidenced cheese counter in central Lons and the right replacement for a Comté affineur the old guide placed here by mistake. Come for the Morbier, which is the family's own; for a run of Comté ages, the Thursday market stalls may serve you better. Hours conflict and nothing dated 2026 turned up, so check before carrying a cool bag across town.", "signature": "The Poulet family's Morbier", "caveat": "Hours conflict between directories and no 2026-dated evidence was found: call or pass by first", "person": "", "status": "unverified", "statusChecked": "2026-10-26", "hook": "A cheesemaking family's own counter under the rue du Commerce arcades: Morbier first, then raclette and tomme.", "dishes": [{"name": "Morbier", "note": "The family's main speciality, per Jura Tourisme", "kind": "dish"}, {"name": "Raclette cheese", "note": "Made by the family; buy a piece for a raclette night on board", "kind": "dish"}, {"name": "Tomme du Jura", "note": "The family's everyday mountain tomme", "kind": "dish"}], "hours": "Year-round as far as found; no annual closure found. Open now and in November-December: no dated evidence either way, check first · Call ahead: directory snapshots (villepratique.fr, undated) show different hours, one closing at 19:00, another at 12:30", "price_range": "By weight; no prices found (Oct 2026)", "reservation": "Walk-in; ask a day ahead for a large order", "neighborhood": "Rue du Commerce", "signal_chip": {"label": "4 generations", "full": "The Poulet family, cheesemakers for four generations, selling their own Morbier, raclette and tomme du Jura", "cosign": "Jura Tourisme"}, "badge": "FROMAGER", "category": "street"},
    {"id": "v10-p-tisserie-chocolaterie-pelen", "cat": "shop", "tier": "several", "priority": 10, "badge": "CHOCOLATIER 1899", "name": "Chocolaterie Pelen", "short": "Pâtisserie Chocolaterie ", "tags": [], "productTags": ["Cafe", "Bread"], "why": "Joseph Pelen opened as confectioner and chocolatier in 1899, and the house kept the Prince d'Orange name he took in 1902. The boutique on rue Saint-Désiré is Belle Époque and runs over two floors, with a tea room upstairs. Pelen is one of very few French chocolatiers to roast its own cocoa beans, and Arnaud Pelen, of the family, makes the praliné. Regulars come back for the écureuil, the squirrel-shaped house speciality.", "address": "1 rue Saint-Désiré, 39000 Lons-le-Saunier", "phone": "+33 3 84 24 13 32", "hours": "Year-round; no annual closure found. Open now and November-December: listed daily including Sunday morning; Christmas hours not published · Mon 09:30-12:00, 14:30-19:00; Tue-Fri 09:00-12:15, 14:30-19:00; Sat 09:00-12:30, 14:30-19:00; Sun 09:00-12:30 (myboulange.fr, undated; the May 2026 record gave different hours for the rue Blaise Pascal site: call ahead)", "maps": "https://www.google.com/maps/search/?api=1&query=Pâtisserie+Chocolaterie+Pelen+Lons-le-Saunier", "price_range": "Pastries and chocolates, about 3-8 € a piece in May 2026 (not re-checked)", "reservation": "Walk-in", "status": "unverified", "statusChecked": "2026-10-26", "hook": "Lons's family chocolatier since 1899, roasting its own beans, with a tea room upstairs.", "verdict": "The chocolate shop Lons is known for, and the place for an edible gift to carry back aboard. Gault&Millau lists it as an artisan. Recent reviews are mixed: praise for the pastries and the écureuil, complaints about prices, early closing and a cool welcome, with a newer note that the tea room has improved. Buy the chocolate; do not count on a late coffee.", "signature": "The écureuil, and the Galet de Chalain praliné-nougatine", "caveat": "The shop is 1 rue Saint-Désiré in the centre; rue Blaise Pascal is the industrial-zone site. Tea room closes early", "person": "Arnaud Pelen (chocolatier)", "dishes": [{"name": "Écureuil", "note": "The squirrel-shaped house speciality regulars return for", "kind": "sweet"}, {"name": "Galet de Chalain", "note": "Nougatine shell, almond-hazelnut praliné, cocoa coating; created 1984 per the May 2026 record, not re-verified now", "kind": "sweet"}, {"name": "Chocolate from house-roasted beans", "note": "Pelen roasts its own cocoa (Lyon Capitale, 2012)", "kind": "sweet"}, {"name": "Praliné bonbons", "note": "Arnaud Pelen's line in the workshop", "kind": "sweet"}, {"name": "Ice cream", "note": "Mentioned in visitor reviews", "kind": "sweet"}], "neighborhood": "Rue Saint-Désiré", "signal_chip": {"label": "Since 1899", "full": "Family chocolatier since 1899, roasts its own beans; listed by Gault&Millau as an artisan", "cosign": "Gault&Millau; Jura Tourisme; SIRENE (1 rue Saint-Désiré)"}, "category": "street"}
