  const GEMS = [{"id": "gem-clavelin", "pattern": "clavelin", "tag": "Jura gem · born here", "name": "The bottle that is the rule", "story": "Vin Jaune is sold in one bottle only, the squat 62 cl clavelin. The usual explanation is that it is what is left of a litre after six years under the veil, when part of the wine has evaporated through the barrel. A Vin Jaune in a 75 cl bottle is not one.", "where": "Any cellar on the slope; Château-Chalon makes nothing else."}, {"id": "gem-cancoillotte", "pattern": "cancoillotte", "tag": "Franche-Comté gem · born here", "name": "The cheese you pour", "story": "Cancoillotte is melted skimmed-milk curd with butter and garlic or wine, sold cold in jars and poured warm over potatoes or a Morteau. It is the cheese of the region’s kitchens and almost unknown outside it.", "where": "Every market in Lons; the fromagers of the arcades."}, {"id": "gem-morteau", "pattern": "Morteau", "tag": "Haut-Doubs gem · born here", "name": "The sausage with a peg", "story": "The Morteau is smoked for days in the tuyé, the pyramid chimney of a mountain farm, and closed with a small wooden peg, the cheville: look for it on the counter. Never prick it, and simmer it slowly.", "where": "The Thursday market in Lons; the charcutiers’ stalls."}];
